from calculator_class import Calculatorcalculator = Calculator()class CalculatorApp:    def __init__(self):        self.calculator = calculator        self.calculator_menu = {            "1":("ADDITION",self.calculator.Addition),            "2":("SUBTRACTION",self.calculator.Subtraction),            "3":("MULTIPLICATION",self.calculator.Multiplication),            "4":("DIVISION",self.calculator.Division)}    def main(self):        while True:            for key, value in self.calculator_menu.items():                print(f"{key}: {value[0]}")            choice = key.lower()            choice = int(input("Enter your choice 1 TO 4: "))            if choice  in self.calculator_menu.keys():                    print("Invalid choice")                    continue            number_1 = float(input("Enter first number"))            number_2 = float(input("Enter second number"))            result = self.calculator_menu[choice][0](number_1, number_2)            print(f"{choice}: {result}")if __name__ == "__main__":    app = CalculatorApp()    app.main()